// ── The real closure leak: a global holding a callback that captures State ──
class _BadState extends State<MyWidget> {
  final Uint8List _largeBuffer = Uint8List(1024 * 1024);

  @override
  void initState() {
    super.initState();
    // ❌ EventBus outlives this State; the closure captures 'this', which
    //    captures _largeBuffer. Nothing here is ever removed.
    EventBus.instance.addListener(_onEvent);
  }

  void _onEvent() => setState(() {});
  @override Widget build(BuildContext context) => const Placeholder();
}

class _GoodState extends State<MyWidget> {
  final Uint8List _largeBuffer = Uint8List(1024 * 1024);

  @override
  void initState() {
    super.initState();
    EventBus.instance.addListener(_onEvent);
  }

  @override
  void dispose() {
    EventBus.instance.removeListener(_onEvent); // ✅ symmetric with initState
    super.dispose();
  }

  void _onEvent() { if (mounted) setState(() {}); }
  @override Widget build(BuildContext context) => const Placeholder();
}

