// Paginated alternative for endless feeds — fetch the next page BEFORE the
// user reaches the bottom, so no spinner interrupts the scroll.
class _FeedState extends State<Feed> {
  final _scroll = ScrollController();

  @override
  void initState() {
    super.initState();
    _scroll.addListener(() {
      final p = _scroll.position;
      if (p.pixels > p.maxScrollExtent - 800) widget.onLoadMore();
    });
  }

  @override
  void dispose() { _scroll.dispose(); super.dispose(); }

  @override
  Widget build(BuildContext context) => ListView.builder(
        controller: _scroll,
        itemExtent: 96,
        itemCount: widget.posts.length,
        itemBuilder: (_, i) => PostTile(post: widget.posts[i]),
      );
}
