class JankReporter {
  JankReporter(this._analytics);

  final Analytics _analytics;
  final _slow = <String, int>{};
  int _frames = 0;

  void start() {
    SchedulerBinding.instance.addTimingsCallback(_onTimings);
  }

  void _onTimings(List<FrameTiming> timings) {
    final budget = _refreshBudget();          // 16.7ms at 60Hz, 8.3ms at 120Hz
    for (final t in timings) {
      _frames++;
      final build = t.buildDuration;
      final raster = t.rasterDuration;
      if (t.totalSpan <= budget) continue;
      final phase = raster > build ? 'raster' : 'ui';
      _slow['${currentScreen.value}/$phase'] =
          (_slow['${currentScreen.value}/$phase'] ?? 0) + 1;
    }
    if (_frames >= 600) _flush();             // roughly every ten seconds
  }

  Duration _refreshBudget() {
    final hz = WidgetsBinding.instance.platformDispatcher.views.first.display
        .refreshRate;
    return Duration(microseconds: (1000000 / hz).round());
  }

  void _flush() {
    if (_slow.isNotEmpty) {
      _analytics.log('jank', {
        'frames': _frames,
        'slow': Map.of(_slow),
        'device': deviceTier,                 // low / mid / high
        'os': osVersion,
        'build': appVersion,
      });
    }
    _slow.clear();
    _frames = 0;
  }
}

